import{_ as e,o as a,c as n,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const c=JSON.parse('{"title":"Phrasing","description":"","frontmatter":{},"headers":[],"relativePath":"generators/PHRASING.md","filePath":"generators/PHRASING.md"}'),s={name:"generators/PHRASING.md"};function r(h,t,i,l,d,u){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="phrasing" tabindex="-1">Phrasing <a class="header-anchor" href="#phrasing" aria-label="Permalink to &quot;Phrasing&quot;">​</a></h1><p>A tune written step by step plays every note at one loudness and fills every bar, which is how a music box plays. A singer or a horn player delivers the same tune in lines, the sentences of the tune: each line starts gently, grows toward its most important note and falls away, and a breath follows before the next line starts. Phrasing plays a tune that way. The pattern stays exactly as written, no note is left out and no pitch changes, so another delivery is another setting and never another tune.</p><p>A musician reaches for Phrasing when a tune sounds stiff or run together. Add Phrasing to a chain on the clip that plays the tune.</p><h2 id="line" tabindex="-1">Line <a class="header-anchor" href="#line" aria-label="Permalink to &quot;Line&quot;">​</a></h2><p>Line says how long one sentence of the tune is: &quot;1 bar&quot;, &quot;2 bars&quot; or &quot;4 bars&quot;, counted from the clip&#39;s start. Most sung tunes move in lines of 2 bars. Everything else on the page happens once for each line.</p><h2 id="breath" tabindex="-1">Breath <a class="header-anchor" href="#breath" aria-label="Permalink to &quot;Breath&quot;">​</a></h2><p>A singer has to breathe, and the breath is what tells a listener that one line has ended and another begins. Breath makes a silence after each line by ending the line&#39;s last note early. With &quot;none&quot; the lines run together. With &quot;quick&quot; the last note gives up an eighth note, and with &quot;deep&quot; a quarter note. The last note is only shortened, by half of the note at most, and where the tune already rests at the end of a line nothing is cut.</p><h2 id="rise-and-fall" tabindex="-1">Rise and Fall <a class="header-anchor" href="#rise-and-fall" aria-label="Permalink to &quot;Rise and Fall&quot;">​</a></h2><p>A player does not give every note of a line the same weight. A line grows toward its main note, which Phrasing takes to be the longest note that starts on a strong beat in the line&#39;s second half, and the notes after the main note fall away, the last note softest. A note that starts a bar is a touch louder. The main note stays as loud as written and the notes around the main note are played softer: by a small amount with &quot;a little&quot;, by a clear amount with &quot;a lot&quot;, and not at all with &quot;none&quot;.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Notes says how the notes inside a line are joined. With &quot;choppy&quot; each note is cut short and a space follows, as a player tonguing every note plays. With &quot;flowing&quot; each note is held until the next note starts, which closes the gaps in a tune written with short notes; a note followed by the same pitch stops a moment early, so that the second note is heard to start. With &quot;as written&quot; each note lasts as long as the pattern says. A tune whose notes already touch sounds the same with &quot;flowing&quot; as with &quot;as written&quot;.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Choices</th><th>A new Phrasing starts with</th></tr></thead><tbody><tr><td>Name</td><td><code>ENTER</code> renames it, and every chain using it follows.</td><td></td></tr><tr><td>Line</td><td>&quot;1 bar&quot;, &quot;2 bars&quot;, &quot;4 bars&quot;</td><td>&quot;2 bars&quot;</td></tr><tr><td>Breath</td><td>&quot;none&quot;, &quot;quick&quot;, &quot;deep&quot;</td><td>&quot;quick&quot;</td></tr><tr><td>Rise and fall</td><td>&quot;none&quot;, &quot;a little&quot;, &quot;a lot&quot;</td><td>&quot;a little&quot;</td></tr><tr><td>Notes</td><td>&quot;choppy&quot;, &quot;as written&quot;, &quot;flowing&quot;</td><td>&quot;as written&quot;</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p><code>examples/learning/25_phrasing.yml</code> plays one tune as written and then with one setting changed in each scene, so that each setting is heard alone, and ends with a verse and a chorus sung with the settings together.</p>',15)])])}const p=e(s,[["render",r]]);export{c as __pageData,p as default};
